#include "stdafx.h"#include "AssignRsuPointsVals.h"#include <macros/csvrow.h>#include <fstream>using namespace std;KAssignRsuPointsVals::KAssignRsuPointsVals(  char * _ObjName ):	IBaseModel ( _ObjName ){  ObjName = _ObjName;  TypeObj = RSU_Obj;}KAssignRsuPointsVals::~KAssignRsuPointsVals(){}int KAssignRsuPointsVals::Step1(){  char* Q = setlocale( LC_ALL, "Russian" );  char Path[512];  sprintf_s( Path, _countof(Path), "%sData\\Acy\\AssignRsuPointsVals.csv", GetBasePath());  ifstream file( Path );  aCSVRow_  row(';');  int lineNum = 0;  for( ;file >> row; lineNum++ )  {    if( row.size()<3 )      continue;    if( row[0].size()>1 && row[0].at(0)=='#' )      continue;    KRsuX rsu;    if( rsu.LinkTo( row[1].c_str(), NULL, row[0].c_str() ) )    {      //ASS(0);      continue;    }    LPCSTR pVal = row[2].c_str();    if( strchr( pVal, '.') )      rsu = atof( pVal );    else      rsu = atoi( pVal );  }  return 0;}